import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';

// The API category is generated by docusaurus-plugin-typedoc into `docs/api/typedoc-sidebar.cjs`. On a clean checkout
// that file does not exist until the first build: fall back to an empty slice so that this file still evaluates.
let typedocSidebar: unknown[] = [];

try {
  const generated = require('./docs/api/typedoc-sidebar.cjs');
  typedocSidebar = withUniqueKeys(Array.isArray(generated) ? generated : (generated?.items ?? []), 'api');
} catch {
  typedocSidebar = [];
}

/**
 * Packages of the API reference share labels: categories ("Interfaces", "Functions"...) and some symbols
 * (`EndpointOptions` in the NestJS and Express adapters). Translation keys are built from labels and must be unique, so
 * every item gets a key from its location.
 */
function withUniqueKeys(items: unknown[], prefix: string): unknown[] {
  return items.map((item) => {
    const entry = item as { type?: string; label?: string; items?: unknown[] };

    if (typeof entry.label !== 'string') {
      return item;
    }

    const key = `${prefix}.${entry.label}`;

    return Array.isArray(entry.items) ? { ...entry, key, items: withUniqueKeys(entry.items, key) } : { ...entry, key };
  });
}

const sidebars: SidebarsConfig = {
  guide: [
    'intro',
    {
      type: 'category',
      label: 'Getting started',
      collapsed: false,
      items: ['getting-started/installation', 'getting-started/quick-start'],
    },
    {
      type: 'category',
      label: 'Guides',
      items: [
        'guides/contracts',
        'guides/rest',
        'guides/client',
        'guides/interceptors',
        'guides/errors',
        'guides/angular',
        'guides/code-generation',
        'guides/nestjs',
        'guides/express',
      ],
    },
    {
      type: 'category',
      label: 'Concepts',
      items: ['concepts/architecture', 'concepts/validation', 'concepts/drivers'],
    },
    {
      type: 'category',
      label: 'Reference',
      items: ['reference/packages', 'reference/versioning'],
    },
    // Appended only when TypeDoc has produced its sidebar (Docusaurus rejects an empty category).
    ...(typedocSidebar.length > 0 ? [{ type: 'category' as const, label: 'API', items: typedocSidebar as never }] : []),
  ],
};

export default sidebars;
